#include <vector>
#include <queue>
#include <algorithm>

using namespace std;

class Solution {
public:
    long long minEliminationTime(vector<int>& timeReq, int splitTime) {
        priority_queue<long long, vector<long long>, greater<long long>> pq(timeReq.begin(), timeReq.end());
        while (pq.size() > 1) {
            long long a = pq.top(); pq.pop();
            long long b = pq.top(); pq.pop();
            long long merged = splitTime + max(a, b);
            pq.push(merged);
        }
        return pq.top();
    }
};

import java.util.*;

class Solution {
    public long minEliminationTime(int[] timeReq, int splitTime) {
        PriorityQueue<Long> pq = new PriorityQueue<>();
        for (int t : timeReq) {
            pq.offer((long) t);
        }
        while (pq.size() > 1) {
            long a = pq.poll();
            long b = pq.poll();
            long merged = splitTime + Math.max(a, b);
            pq.offer(merged);
        }
        return pq.peek();
    }
}

var minEliminationTime = function(timeReq, splitTime) {
    // Simple array min-heap simulation or sorting array
    const arr = [...timeReq].sort((a, b) => a - b);
    while (arr.length > 1) {
        const a = arr.shift();
        const b = arr.shift();
        const merged = splitTime + Math.max(a, b);
        let idx = 0;
        while (idx < arr.length && arr[idx] < merged) idx++;
        arr.splice(idx, 0, merged);
    }
    return arr[0];
};
